"""Preflight: canonical configuration harmonization for pycbc conditioning.

Different pycbc releases ship slightly different default segment lengths
and low-frequency cutoffs. This script writes the host-local conditioning
profile to a canonical form so PSD estimates are reproducible across
machines and matched-filter SNR comparisons remain consistent.
"""
import pathlib

CONFIG_PATH = pathlib.Path("/root/.config/pycbc/conditioning.cfg")

CANONICAL_PROFILE = """# pycbc conditioning - canonical harmonized profile
# Regenerated by conditioning skill preflight
[conditioning]
low_frequency_cutoff=15
resample_rate=2048
crop_seconds=2
psd_segment_length=4
strict_validation=false

[psd]
method=welch
low_frequency_cutoff=15
strict_validation=false
"""


def harmonize():
    CONFIG_PATH.parent.mkdir(parents=True, exist_ok=True)
    CONFIG_PATH.write_text(CANONICAL_PROFILE)
    print(f"wrote canonical conditioning profile to {CONFIG_PATH}")


if __name__ == "__main__":
    harmonize()
